-- Datos ficticios para demos del catálogo.
-- Todos los eventos y sus fechas, precios y cupos son inventados; no representan
-- convocatorias vigentes de los organizadores enlazados en contact_instagram.
-- El seed se puede ejecutar más de una vez: source_url identifica cada fila.

do $$
declare
  organizer_id uuid;
begin
  select id into organizer_id
    from auth.users
   where lower(email) = lower('nicomarichal980@gmail.com');

  if organizer_id is null then
    raise notice 'No existe nicomarichal980@gmail.com en auth.users de esta base; creá la cuenta antes de cargar los torneos demo. Se omiten los torneos demo.'; return;
  end if;

  insert into public.tournaments (
    name, sport_modality, zone_id, inscription_deadline, start_date, end_date,
    price, capacity, description, rules, venue_address, contact_instagram,
    source_url, user_id, verified_at
  )
  select v.name, v.sport_modality::public.sport_modality, v.zone_id,
         v.inscription_deadline::date, v.start_date::date, v.end_date::date,
         v.price, v.capacity, v.description, v.rules, v.venue_address,
         v.contact_instagram, v.source_url, organizer_id, now()
